// Social Eagle Lead Import — Validate & Prepare
// Receives payload from Google Apps Script, validates required fields,
// sanitises notes (belt-and-braces), returns clean payload ready for Kylas.

const input = $input.first().json;

// Apps Script sends the payload as the request body, already structured.
// If it was sent with Content-Type: application/json, n8n parses it into
// `body`. If sent as text/plain (some Apps Script UrlFetchApp defaults),
// we need to JSON.parse `body` manually.
let data;
if (input.body && typeof input.body === 'object') {
  data = input.body;
} else if (input.body && typeof input.body === 'string') {
  try {
    data = JSON.parse(input.body);
  } catch (e) {
    throw new Error('Invalid JSON in request body: ' + e.message);
  }
} else {
  // Fallback: the fields may be at the top level
  data = input;
}

// --- Required-field guardrails (Apps Script should have validated, but double-check) ---
const required = ['firstName', 'lastName', 'phoneNumbers', 'source', 'customFieldValues'];
for (const f of required) {
  if (data[f] === undefined || data[f] === null || data[f] === '') {
    throw new Error(`Missing required field: ${f}`);
  }
}

if (!Array.isArray(data.phoneNumbers) || data.phoneNumbers.length === 0) {
  throw new Error('phoneNumbers must be a non-empty array');
}

if (typeof data.customFieldValues !== 'object') {
  throw new Error('customFieldValues must be an object');
}

if (!Array.isArray(data.customFieldValues.cfLeadType) || data.customFieldValues.cfLeadType.length === 0) {
  throw new Error('customFieldValues.cfLeadType must be a non-empty array');
}

if (!Array.isArray(data.customFieldValues.cfSubSourceMultiPicklist) || data.customFieldValues.cfSubSourceMultiPicklist.length === 0) {
  throw new Error('customFieldValues.cfSubSourceMultiPicklist must be a non-empty array');
}

// --- Sanitise notes (strip any lingering line breaks / tabs) ---
if (data.customFieldValues.cfNotesFromLeadImport) {
  data.customFieldValues.cfNotesFromLeadImport = String(data.customFieldValues.cfNotesFromLeadImport)
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/ {2,}/g, ' ')
    .trim();
}

// --- Ensure empty string for optional UTM fields (never null) ---
['utmSource', 'utmMedium', 'utmCampaign', 'utmContent', 'utmTerm'].forEach(k => {
  if (data[k] === null || data[k] === undefined) data[k] = '';
});

// --- Return clean payload ready for Kylas HTTP call ---
return { json: { payload: data } };

// Format the response from Kylas into the shape Apps Script expects.
// Apps Script looks for:  { success: true, leadId: "..." }  or  { success: false, error: "..." }

const resp = $input.first().json;

// When fullResponse + neverError are on, the HTTP node returns:
//   { statusCode, headers, body }
// We need to check statusCode and extract leadId from body.

const statusCode = resp.statusCode || resp.status || 0;
const body = resp.body || resp;

if (statusCode >= 200 && statusCode < 300) {
  // Success — extract Kylas lead ID
  // Kylas returns the created lead object. The ID may be in `id` or similar.
  const leadId = body.id || body.leadId || body._id || '';
  return {
    json: {
      success: true,
      leadId: String(leadId),
      kylasResponse: body
    }
  };
}

// Failure — extract an error message
let errorMessage = 'Unknown error';
if (body && typeof body === 'object') {
  errorMessage = body.message || body.error || body.errorMessage || JSON.stringify(body).substring(0, 200);
} else if (typeof body === 'string') {
  errorMessage = body.substring(0, 200);
}

return {
  json: {
    success: false,
    error: `HTTP ${statusCode}: ${errorMessage}`,
    kylasResponse: body
  }
};
